// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetCardStatementAnalytics The 12 latest statements of a card closed on or before today, oldest first, split as in getStatementAnalytics.
	// (GET /accounts/{id}/statement-analytics)
	GetCardStatementAnalytics(ctx context.Context, request GetCardStatementAnalyticsRequestObject) (GetCardStatementAnalyticsResponseObject, error)
	// RequestExport Request an archive of every fact of the books (SC6, docs/superpowers/specs/2026-10-26-export-design.md).
	// (POST /exports)
	RequestExport(ctx context.Context, request RequestExportRequestObject) (RequestExportResponseObject, error)
	// GetExport The user's export and its status; 404 when none was requested.
	// (GET /exports/current)
	GetExport(ctx context.Context, request GetExportRequestObject) (GetExportResponseObject, error)
	// GetExportContent Download the archive of a ready export; 409 export_not_ready otherwise.
	// (GET /exports/current/content)
	GetExportContent(ctx context.Context, request GetExportContentRequestObject) (GetExportContentResponseObject, error)
	// ImportArchive Restore an export archive into books without facts (N13, export design E4).
	// (POST /imports/archive)
	ImportArchive(ctx context.Context, request ImportArchiveRequestObject) (ImportArchiveResponseObject, error)
	// GetBalanceSeries Daily balance of an account and its sub-accounts, one item per day in [from, to].
	// (GET /reports/balances)
	GetBalanceSeries(ctx context.Context, request GetBalanceSeriesRequestObject) (GetBalanceSeriesResponseObject, error)
	// GetCategoryTotals Totals of each category of a class in [from, to], at most 366 days, in the accrual or cash view (A77).
	// (GET /reports/categories)
	GetCategoryTotals(ctx context.Context, request GetCategoryTotalsRequestObject) (GetCategoryTotalsResponseObject, error)
	// ListCategoryCashPayments Card amounts of one category in the cash view of [from, to], at most 366 days, each naming its statement and payment (N20).
	// (GET /reports/categories/{id}/cash-payments)
	ListCategoryCashPayments(ctx context.Context, request ListCategoryCashPaymentsRequestObject) (ListCategoryCashPaymentsResponseObject, error)
	// GetAccountFlows Booked inflow and outflow of one account, one item per day in [from, to] that has a posting (A119).
	// (GET /reports/flows)
	GetAccountFlows(ctx context.Context, request GetAccountFlowsRequestObject) (GetAccountFlowsResponseObject, error)
	// GetStatementAnalytics A statement split into purchases, installments, charges and credits, per category (P9).
	// (GET /statements/{id}/analytics)
	GetStatementAnalytics(ctx context.Context, request GetStatementAnalyticsRequestObject) (GetStatementAnalyticsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

